import csv
sens="108335ab-9ad0-5222-b9a5-88d998152c65"
sp="335c2ab2-c7e3-551f-8bdc-96b15c59e4a8"
D={sens:[],sp:[]}
for ts,tm,v in csv.reader(open(VALUES_CSV)):
    if ts in D:
        D[ts].append((tm,float(v)))
def mean_dev(date):
    pairs=[]
    smap={}
    for tm,v in D[sp]:
        smap[tm]=v
    for tm,v in D[sens]:
        if tm.startswith(date):
            hr=int(tm[11:13])
            if 8<=hr<=18 and tm in smap:
                pairs.append(v-smap[tm])
    return sum(pairs)/len(pairs), len(pairs)
m1,n1=mean_dev('2018-04-13')
m2,n2=mean_dev('2018-07-04')
print("2018-04-13",m1,n1)
print("2018-07-04",m2,n2)
print("increase" if m2>m1 else "decrease")
